/**
 * 설 명 : ajax 통신  공통 함수 
 */
$.httpAjax = function(url, data, options, fncCallBack, fncCallBackErr) {
  
  	var async = true;
    var contentType = "application/json;";
  	//var contentType ="application/x-www-form-urlencoded; charset=UTF-8";
	var loading = true; 
	
//	var data={
//		bbsId :"1111",
//	};
		
   	return $.ajax({
     	url         : url,
		headers     : {"Accept" : "application/json"},
		data        : JSON.stringify(data),
        async       : async,
        type        : "POST",
		contentType : contentType,
   		beforeSend  : function(){
			//로딩바
			if (loading) {
				 setTimeout(function(){
					fnc_loading();
				},1000);
			}
  		},
		success     : function(response){
	 	 	fncCallBack(response);
	 		if (loading) {
			 	fnc_loadingStop();
			}
	 	}, 
	 	error       : function(response){ 
	 		fncCallBackErr(response);
	  		console.log(JSON.stringify(response));
	         if (loading) {
	 			fnc_loadingStop();
			}
  			return;
	 	},
	 	complete    : function() {
	  	}
	});
}

$.formAjax = function(url, formData, options, fncCallBack, fncCallBackErr) {
	  
	var async = true;
	var enctype = "multipart/form-data;";
	var loading = true; 
	return $.ajax({
		cache       : false,
		url         : url,
		processData : false,
		contentType : false,
		enctype		: enctype,
		type        : "POST",
		data        : formData,
		success     : function(response){
			//console.log(response); 
			fncCallBack(response);
		}, 
		error       : function(response){ 
			fncCallBackErr(response);
			//console.log(JSON.stringify(response));
			return;
		}
	});
}


/**
