/**
 * 첨부파일 확장자 확인
 */
function fncCheckFileExtension(file, ext) {
	var fileNm = file.files[0].name.toLowerCase();
	var fileNmLstDot = fileNm.lastIndexOf(".");
	var fileNmLength = fileNm.length;
	var fileExt = fileNm.substring(fileNmLstDot + 1, fileNmLength);
	
	if (!ext.includes(fileExt)) {
		return false;
	}
	
	return true;
}

/**
 * 첨부파일 크기 확인
 */
function fncCheckFileSize(file, maxSize) {
	var fileSize = file.files[0].size;
	maxSize = maxSize * 1024 * 1024; // MB -> B

	if (fileSize > maxSize) {
		return false;
	}
	
	return true;
}

/**
 * 첨부파일 크기 가져오기
 */
function fncGetFileSize(file) {
	var fileSize = file.files[0].size;
	var unit = ["Byte", "KB", "MB", "GB", "TB", "PB"];
	var e = Math.floor(Math.log(fileSize) / Math.log(1024));
	return (fileSize / Math.pow(1024, e)).toFixed(0) + " " + unit[e];
}


function fnc_loading(){
