}

function fnc_loadingStop(){
}


$.makePagination = function(pagination, likePageFnName) {
	var curPage = pagination.currentPageNo;
	
	var endPage = Math.ceil((curPage+1)/10.0) * 10; // 1 - 10
	if(curPage + 10 == endPage) {
		endPage -= 10;
	}
	var startPage = endPage - 9 ;
	
	if( endPage > pagination.totalPageCount ) {
		endPage = pagination.totalPageCount ;
	}
	
	var html = "";

	var prevPagination = ( startPage - 1.0 );
	if( startPage > 1  ) {  // 이전 버튼 
		html += '<a href="#" onclick="' + likePageFnName + '(1); return false;" class="page first">처음 목록</a>';
		html += '<a href="#" class="page prev" onclick="' + likePageFnName + '(' + prevPagination + '); return false;">이전 목록</a>';
	} else {
		html += '<a href="#" onclick="' + likePageFnName + '(1); return false;" class="page first">처음 목록</a>';
		html += '<a href="#" class="page prev" onclick="' + likePageFnName + '(1); return false;">이전 목록</a>';
	}
	
	for( i = startPage; i <= endPage; i++) {
		if(i == curPage) {
			html += '<a href="#" class="num current" title="현재페이지">' + curPage + '</a>';
		} else {
			html += '<a href="#" class="num" onclick="' + likePageFnName + '(' + i + '); return false;">' + i + '</a>';
		}
	}
	
	var nextPagination = ( endPage + 1.0 );
	if( endPage < pagination.totalPageCount ) {  // 다음 버튼 
		html += '<a href="#" class="page next" onclick="' + likePageFnName + '(' + nextPagination + '); return false;">다음 목록</a>';
		html += '<a href="#" class="page last" onclick="' + likePageFnName + '(' + pagination.totalPageCount + '); return false;">마지막 목록</a>';
	}
	
	return html;
}



// SNS 공유
function fncShareSNS(type, pageUrl, content, imgUrl) {
	var sendUrl = "";

	switch (type) {
		case "x":
			sendUrl = "https://twitter.com/intent/tweet/?text=" + encodeURIComponent(content) + "%20(" + encodeURIComponent(pageUrl)+")";
			break;
		case "fb":
			sendUrl = 'https://www.facebook.com/sharer/sharer.php?t=' + encodeURIComponent(content) + '&u=' + encodeURIComponent(pageUrl);
			break;
	}
	
	if(type == "kakao"){
		fncShareKakao(pageUrl, content, imgUrl);
	} else {
		window.open(sendUrl, "SNS_POP", "width=1024, height=800");		
	}
	
}


function fncShareKakao(pageUrl, title, imgUrl) {
	var url = location.href;
	var shareUrl = url;			// 공유하려는 페이지 url
	var docTitle = document.title;		// 공유하려는 페이지의 제목

	var UserAgent = navigator.userAgent;
	
	if ( UserAgent.match(/iPhone|iPad|iPod|Android|Windows CE|BlackBerry|Symbian|Windows Phone|webOS|Opera Mini|Opera Mobi|POLARIS|IEMobile|lgtelecom|nokia|SonyEricsson/i) == null) {
		//commonUI.msgPop('alert', "카카오톡 공유는 모바일에서만 사용 가능합니다.");
		alert("카카오톡 공유는 모바일에서만 사용 가능합니다.");
		
	}else{
		// 모바일인 경우 카카오톡 버튼 생성
		
		var baseUrl = window.location.protocol + "//" + window.location.hostname + (("" == window.location.port)? "" : (":" + window.location.port));
		var imageUrl = "";
		if (undefined !== imgUrl && "" != imgUrl){
			imageUrl = baseUrl + imgUrl;
		}  else {
			imageUrl = baseUrl + "/images/common/img_top_logo.png"; 
		}
		
		Kakao.Link.sendDefault({
			objectType: 'feed',
			content:{
				title: docTitle,
				description:title,
				imageUrl: imageUrl,
				link:{
					mobileWebUrl: pageUrl,
					webUrl: pageUrl
				}
			},
			buttons:[{
				title:'자세히 보기',
				link:{
					mobileWebUrl: pageUrl,
					webUrl: pageUrl
				}
			}]
		});
	}
}

function filterUrl(url){
	var filteredUrl = url;
	var defaultUrl = location.origin + "/main.do";
	if (!filteredUrl.startsWith(defaultUrl)){
		return "/main.do";
	}
	return filteredUrl;
}

/**
 * 입력박스의 입력되는 글자byte수를 체크하고 제한한다.
 * @param item   입력박스 이름
 * @param viewId 현재 입력된 글자수를 보여줄 span태그 아이디
 * ex)
 *         현재 <span id='cmntlen' style=''>0</span>byte
 *         <textarea onKeyUp='inputCheckLen(this, "cmntLen", 100)'></textarea>
 */
function inputCheckLen(item, viewId, limit){
	var len = LengthCheck(item.value);
	if(len>limit){
		var msg = limit+'byte를 초과할 수 없습니다.';
		commonUI.msgPop ? commonUI.msgPop('alert', msg) : alert(msg);
		item.value = strCutByte(item.value, limit);
	}
	len = LengthCheck(item.value);
	var obj = document.getElementById(viewId);
	obj.innerHTML = len;
}

//문자열 개수
function LengthCheck(message) {
	var nbytes = 0;

	for (i=0; i<message.length; i++) {
		var ch = message.charAt(i);
		if (escape(ch).length > 4) {
			nbytes += 2;
		} else if (ch != '\r') {
			nbytes++;
		}
	}

	return nbytes;
}

