$.makePagination = function(pagination, likePageFnName) {
	var curPage = pagination.currentPageNo;
	
	var endPage = Math.ceil((curPage+1)/10.0) * 10; // 1 - 10
	if(curPage + 10 == endPage) {
		endPage -= 10;
	}
	var startPage = endPage - 9 ;
	
	if( endPage > pagination.totalPageCount ) {
		endPage = pagination.totalPageCount ;
	}
	
	var html = "";

	var prevPagination = ( startPage - 1.0 );
	if( startPage > 1  ) {  // 이전 버튼 
		html += '<a href="#" onclick="' + likePageFnName + '(1); return false;" class="page first">처음 목록</a>';
		html += '<a href="#" class="page prev" onclick="' + likePageFnName + '(' + prevPagination + '); return false;">이전 목록</a>';
	} else {
		html += '<a href="#" onclick="' + likePageFnName + '(1); return false;" class="page first">처음 목록</a>';
		html += '<a href="#" class="page prev" onclick="' + likePageFnName + '(1); return false;">이전 목록</a>';
	}
	
	for( i = startPage; i <= endPage; i++) {
		if(i == curPage) {
			html += '<a href="#" class="num current" title="현재페이지">' + curPage + '</a>';
		} else {
			html += '<a href="#" class="num" onclick="' + likePageFnName + '(' + i + '); return false;">' + i + '</a>';
		}
	}
	
	var nextPagination = ( endPage + 1.0 );
	if( endPage < pagination.totalPageCount ) {  // 다음 버튼 
		html += '<a href="#" class="page next" onclick="' + likePageFnName + '(' + nextPagination + '); return false;">다음 목록</a>';
		html += '<a href="#" class="page last" onclick="' + likePageFnName + '(' + pagination.totalPageCount + '); return false;">마지막 목록</a>';
	}
	
	return html;
}



